                return _handle_vulnerability_item(
                    method,
                    environ,
                    malformed_id,
                    raw_vulnerability_id,
                    start_response,
                )
            if separator and "/vulnerability-exceptions/" in suffix:
                # Fallback for a separator inside the id segment of an
