                return _handle_vulnerability_exceptions(
                    method,
                    environ,
                    suffix[: -len("/vulnerability-exceptions")],
                    start_response,
                )
            if separator and suffix.endswith("/sbom"):
                # Fallback for a separator inside the id segment so the
